def is_power_of_5(x):
    if x <= 0:
        return False
    if x == 1:
        # 5^0 = 1. Since n >= 3, 2^n - 3 >= 5, so this case shouldn't happen for x derived from n>=3.
        return True
    while x > 1 and x % 5 == 0:
        x //= 5
    return x == 1

print("Testing n from 3 to 20:")
results = []
for n in range(3, 21):
    X = (2**n) - 3
    if is_power_of_5(X):
        # Find k such that 5^k = X
        # Since X is positive, we can use log
        import math
        k = round(math.log(X, 5))
        # Verify k is correct (to handle potential floating point errors, though should be exact here)
        if 5**k == X:
            results.append((n, k))

for n, k in results:
    print(f"Found solution: n={n}, k={k}, 2^{n} - 3 = 5^{k}")

print("\nAll results:", results)

